MagickBooleanType SkipMipmapImages(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
    if (!dds_info->has_mipmaps || !(dds_info->is_texture || dds_info->is_cubemap))
        return MagickTrue;

    MagickBooleanType status = MagickTrue;
    size_t width = image->columns;
    size_t height = image->rows;

    for (int level = 1; level < dds_info->mipmap_levels; level++) {
        size_t level_width = width / 2;
        size_t level_height = height / 2;

        size_t level_size = level_width * level_height * pixel_size;
        if (SeekImageBlob(image, level_size, SEEK_CUR) != (ssize_t)level_size) {
            (void) ThrowMagickException(exception, GetMagickModule(), CoderError, "UnableToSkipMipmapData", "%s", image->filename);
            return MagickFalse;
        }

        width = level_width;
        height = level_height;
    }

    return status;
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
    if ((dds_info->mipmap_count > 1) && (dds_info->is_texture || dds_info->is_cube_map)) {
        MagickSizeType width = image->columns;
        MagickSizeType height = image->rows;

        for (size_t level = 1; level < dds_info->mipmap_count; ++level) {
            MagickSizeType level_width = width > 1 ? width / 2 : 1;
            MagickSizeType level_height = height > 1 ? height / 2 : 1;
            MagickSizeType level_size = level_width * level_height * pixel_size;

            if (SeekBlob(image, level_size, SEEK_CUR) != 0) {
                (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToSkipMipmap", "DDS file is incomplete or corrupt");
                return MagickFalse;
            }

            width = level_width;
            height = level_height;
        }
    }

    return MagickTrue;
}

MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
  MagickBooleanType status = MagickTrue;
  size_t width = image->columns;
  size_t height = image->rows;
  size_t skip_size;

  if ((dds_info->mipmaps > 0) && (IsTexture(dds_info) || IsCubeMap(dds_info))) {
    while (dds_info->mipmaps > 0) {
      skip_size = width * height * pixel_size;
      if (SeekImageBlob(image, skip_size, SEEK_CUR) == -1) {
        (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError, "Unable to skip mipmap data", "%s", image->filename);
        status = MagickFalse;
        break;
      }

      dds_info->mipmaps--;
      width = (width >> 1) ? (width >> 1) : 1;
      height = (height >> 1) ? (height >> 1) : 1;
    }
  }

  return status;
}

